+                        ExtValueWithIdentityReplacement.class,
+                        SC_SERIALIZABLE,
+                        ICE
+                ),
+
+                Arguments.of(
+                        ValueWithDeserializer.class,
+                        SC_EXTERNALIZABLE,
+                        ICE
